---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Slider: Named stops, a stepped scale and a range, with the agent's recommended value marked on the track.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change slider.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './slider.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="slider" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="sdx panel">
  <div class="sdx-b">
    <div class="sdx-h"><span id="sdx-cr">Creativity</span><span class="sdx-v num"></span></div>
    <div class="sdx-tr" data-s="cr"><span class="sdx-rail"><i class="sdx-fill"></i></span><button class="sdx-rec" aria-label="Use the recommended value" data-tip="Recommended by the agent: 0.4"><svg class="i xs"><use href="#i-spark"/></svg></button><span class="sdx-k" role="slider" tabindex="0" aria-labelledby="sdx-cr"><i class="sdx-kb"></i><span class="sdx-tt num"></span></span></div>
    <div class="sdx-stops"><button data-v="0">Precise</button><button data-v="0.5">Balanced</button><button data-v="1">Creative</button></div>
    <p class="sdx-sm" aria-live="polite"><span></span></p>
  </div>
  <div class="sdx-b">
    <div class="sdx-h"><span id="sdx-mx">Tool calls per run</span><span class="sdx-v num"></span></div>
    <div class="sdx-tr" data-s="mx"><span class="sdx-rail"><i class="sdx-fill"></i></span><span class="sdx-k" role="slider" tabindex="0" aria-labelledby="sdx-mx"><i class="sdx-kb"></i><span class="sdx-tt num"></span></span></div>
    <div class="sdx-ticks num"></div>
  </div>
  <div class="sdx-b">
    <div class="sdx-h"><span id="sdx-co">Cost per run</span><span class="sdx-v num"></span></div>
    <div class="sdx-tr" data-s="co"><span class="sdx-rail"><i class="sdx-fill"></i></span><span class="sdx-k" role="slider" tabindex="0" aria-label="Lowest cost per run"><i class="sdx-kb"></i><span class="sdx-tt num"></span></span><span class="sdx-k" role="slider" tabindex="0" aria-label="Highest cost per run"><i class="sdx-kb"></i><span class="sdx-tt num"></span></span></div>
    <div class="sdx-ends muted num"><span>$0.00</span><span>$1.00</span></div>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './slider.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Slider ---------- */
/* three sliders on one grey track style: a knob you drag or move with the keys, the value over it while it moves, and the
   part of the track it covers in the accent */
.sdx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-4)}
.sdx-b{display:flex;flex-direction:column;gap:var(--dm-s-1)}
.sdx-b+.sdx-b{padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.sdx-h{display:flex;align-items:baseline;justify-content:space-between;gap:var(--dm-s-2);font-size:13px}
.sdx-v{color:var(--dm-fg2);font-size:12.5px}
.sdx-tr{position:relative;height:32px;touch-action:none;cursor:pointer;margin:0 10px}
.sdx-rail{position:absolute;left:-10px;right:-10px;top:50%;height:6px;margin-top:-3px;border-radius:calc(3px * var(--dm-rk));background:var(--dm-chip);overflow:hidden}
.sdx-fill{position:absolute;top:0;bottom:0;left:0;width:0;background:var(--dm-accent-mark,var(--dm-accent))}
/* the knob: a white squircle you drag (owner, 5 Nov), white in dark mode too, on a hairline and a soft shadow; square in Blueprint.
   It is playful in the hand (owner, 5 Nov): grabbed, it springs up and lifts; dragged, it leans into the way it moves and
   rights itself when you stop; let go, it bounces back down; and it gives a little hop when it snaps to the agent's mark.
   The body (.sdx-kb) moves, so the value above it stays upright. A press never shows the focus ring (.ptr); keys do */
.sdx-k{position:absolute;top:50%;left:0;width:20px;height:20px;margin:-10px 0 0 -10px;border-radius:calc(6px * var(--dm-rk));cursor:grab;z-index:2}
.sdx-kb{position:absolute;inset:0;border-radius:calc(6px * var(--dm-rk));corner-shape:squircle;background:#fff;box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-line) 70%,transparent),0 1px 2px rgba(0,0,0,.12),0 2px 6px rgba(0,0,0,.08);transform:rotate(var(--dm-tilt,0deg)) scale(var(--dm-ks,1));transition:transform .5s cubic-bezier(.34,1.56,.64,1),box-shadow .25s var(--dm-ease)}
.sdx-tr.drag .sdx-k.on .sdx-kb{--dm-ks:1.2;box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-line) 70%,transparent),0 4px 8px rgba(0,0,0,.12),0 10px 22px rgba(0,0,0,.14);transition:transform .22s cubic-bezier(.34,1.56,.64,1),box-shadow .2s var(--dm-ease)}
.sdx-k.ptr:focus-visible{outline:none}
:root:not([data-style="soft"]) .sdx-k:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .sdx-kb:not(:where([data-style="soft"],[data-style="soft"] *)){border-radius:0}
:root:not([data-style="soft"]) .sdx-kb:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-rail) 70%,transparent)}
:root:not([data-style="soft"]) .sdx-tr.drag .sdx-k.on .sdx-kb:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-rail) 70%,transparent),0 6px 14px rgba(0,0,0,.18)}
@media (prefers-reduced-motion:reduce){.sdx-kb{transition:none;transform:none!important}}
.sdx-k:focus-visible{outline-offset:3px}
.sdx-tr.glide .sdx-k{transition:left .45s cubic-bezier(.34,1.3,.64,1)}
.sdx-tr.glide .sdx-fill{transition:left .45s var(--dm-ease),width .45s var(--dm-ease)}
.sdx-tr.drag .sdx-k.on{cursor:grabbing}
.sdx-tt{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translateX(-50%) translateY(4px) scale(.7);transform-origin:50% 100%;padding:3px var(--dm-s-2);border-radius:var(--dm-r-pill);background:var(--dm-ink);color:var(--dm-on-ink);font-size:11px;white-space:nowrap;opacity:0;transition:opacity .15s,transform .35s cubic-bezier(.34,1.56,.64,1);pointer-events:none}
.sdx-k.on.say .sdx-tt,.sdx-tr.drag .sdx-k.on .sdx-tt{opacity:1;transform:translateX(-50%) translateY(0) scale(1)}
@media (hover:hover) and (pointer:fine){.sdx-k:hover .sdx-tt{opacity:1;transform:translateX(-50%) translateY(0) scale(1)}}
.sdx-tr.drag .sdx-k.on .sdx-tt{transform:translateX(-50%) translateY(-4px) scale(1)}
/* the value the agent recommends: a mark over the track that you can press, and a notch in it; a knob dropped near it snaps to it */
.sdx-rec{position:absolute;top:-9px;width:20px;height:20px;margin-left:-10px;display:grid;place-items:center;border-radius:calc(6px * var(--dm-rk));color:var(--dm-accent-fg,var(--dm-accent));z-index:1;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.sdx-rec:hover{background:var(--dm-accent-bg)}}
.sdx-rec .i{width:12px;height:12px}
.sdx-tr[data-s="cr"] .sdx-rail{box-shadow:none}
.sdx-notch{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--dm-surface)}
.sdx-stops{display:flex;justify-content:space-between;margin:0 -6px}
.sdx-stops button{height:24px;padding:0 6px;border-radius:calc(6px * var(--dm-rk));font-size:12px;color:var(--dm-muted);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.sdx-stops button:hover{background:var(--dm-row);color:var(--dm-fg)}}
.sdx-stops button[aria-pressed="true"]{color:var(--dm-fg)}
.sdx-sm{margin:var(--dm-s-1) 0 0;min-height:calc(2 * 1.5em);font-size:13px;line-height:1.5;color:var(--dm-fg2)}
.sdx-ticks{position:relative;height:28px;margin:-6px 10px 0}
.sdx-ticks button{position:absolute;top:0;display:flex;flex-direction:column;align-items:center;gap:3px;width:32px;margin-left:-16px;padding-top:2px;font-size:11.5px;color:var(--dm-muted);border-radius:calc(6px * var(--dm-rk));transition:color var(--dm-t-fast)}
.sdx-ticks button i{width:1px;height:5px;background:var(--dm-faint)}
.sdx-ticks button[aria-pressed="true"]{color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){.sdx-ticks button:hover{color:var(--dm-fg)}}
.sdx-ticks button[aria-pressed="true"] i{background:var(--dm-fg2)}
.sdx-ends{display:flex;justify-content:space-between;font-size:11.5px;margin-top:-2px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, swap } from '../core/core.js';
DM.def('slider', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{spark}', I('spark','xs'));
  const q = s => $(`.sdx-tr[data-s="${s}"]`, r);
  /* one track: its knobs, the range they run over and how values read. Pointer: press anywhere on the track and the nearest
     knob comes to it and follows. Keys on a knob: arrows one step, Shift with an arrow or Page Up/Down ten, Home and End the
     ends. Two knobs never cross */
  function track(tr, o){
    const ks = $$('.sdx-k', tr), fill = $('.sdx-fill', tr), v = o.vals.slice();
    const pct = x => (x - o.min) / (o.max - o.min) * 100, snap = x => Math.round((x - o.min) / o.step) * o.step + o.min, fix = x => +x.toFixed(4);
    const clamp = (i, x) => { let lo = o.min, hi = o.max; if (ks.length > 1){ if (i === 0) hi = v[1] - o.step; else lo = v[0] + o.step; } return Math.max(lo, Math.min(hi, x)); };
    const paint = () => {
      ks.forEach((k, i) => { k.style.left = pct(v[i]) + '%'; $('.sdx-tt', k).textContent = o.fmt(v[i]); k.setAttribute('aria-valuemin', ks.length > 1 && i ? fix(v[0] + o.step) : o.min); k.setAttribute('aria-valuemax', ks.length > 1 && !i ? fix(v[1] - o.step) : o.max); k.setAttribute('aria-valuenow', fix(v[i])); k.setAttribute('aria-valuetext', o.text(v[i], i)); });
      fill.style.left = ks.length > 1 ? pct(v[0]) + '%' : '0'; fill.style.width = (ks.length > 1 ? pct(v[1]) - pct(v[0]) : pct(v[0])) + '%';
      o.change && o.change(v);
    };
    // a little hop when a knob snaps onto the agent's mark
    const hop = i => { if (REDUCE) return; $('.sdx-kb', ks[i]).animate([{ transform:'scale(1.2)' }, { transform:'scale(1.38)', offset:.35 }, { transform:'scale(1.2)' }], { duration:320, easing:'cubic-bezier(.34,1.56,.64,1)' }); };
    const set = (i, x, near) => { x = clamp(i, snap(x)); let hit = false; if (near != null && o.rec != null && Math.abs(x - o.rec) <= near){ hit = true; x = o.rec; } if (fix(x) === fix(v[i])) return; v[i] = fix(x); paint(); if (hit && tr.classList.contains('drag')) hop(i); };
    // a value set from outside (a stop, the recommended mark, a tick) glides there: the knob and the fill ease across while
    // the value lands at once
    let gt = 0;
    const glide = (i, x) => { say(i); tr.classList.add('glide'); clearTimeout(gt); gt = setTimeout(() => tr.classList.remove('glide'), 500); set(i, x); };
    let sayT = 0; const say = i => { ks.forEach((k, j) => k.classList.toggle('on', j === i)); ks[i].classList.add('say'); clearTimeout(sayT); sayT = setTimeout(() => ks[i].classList.remove('say'), 1200); };
    let act = 0;
    const at = e => { const b = tr.getBoundingClientRect(); return o.min + (o.max - o.min) * Math.max(0, Math.min(1, (e.clientX - b.left) / b.width)); };
    tr.addEventListener('pointerdown', e => {
      if (e.target.closest('.sdx-rec') || e.button) return;
      const x = at(e); act = ks.length > 1 ? (Math.abs(x - v[0]) <= Math.abs(x - v[1]) ? (x < v[0] ? 0 : Math.abs(x - v[0]) < Math.abs(x - v[1]) ? 0 : 1) : 1) : 0;
      tr.classList.remove('glide'); tr.setPointerCapture(e.pointerId); tr.classList.add('drag'); ks.forEach((k, j) => k.classList.toggle('on', j === act));
      ks.forEach(k => k.classList.add('ptr'));
      e.preventDefault(); ks[act].focus({ preventScroll:true, focusVisible:false }); set(act, x, (o.max - o.min) * .05);
      // it leans into the way it moves, as far as 16 degrees, and rights itself once the pointer rests
      let lx = e.clientX, lt = e.timeStamp, rest = 0; const kb = $('.sdx-kb', ks[act]);
      tr.onpointermove = ev => { set(act, at(ev), (o.max - o.min) * .05);
        if (REDUCE) return; const dt = Math.max(8, ev.timeStamp - lt), vx = (ev.clientX - lx) / dt; lx = ev.clientX; lt = ev.timeStamp;
        kb.style.setProperty('--dm-tilt', Math.max(-16, Math.min(16, vx * 14)).toFixed(1) + 'deg'); clearTimeout(rest); rest = setTimeout(() => kb.style.setProperty('--dm-tilt', '0deg'), 90); };
      tr.onpointerup = tr.onpointercancel = () => { tr.classList.remove('drag'); tr.onpointermove = null; clearTimeout(rest); kb.style.setProperty('--dm-tilt', '0deg');
        // let go, it drops back with a bounce
        if (!REDUCE) kb.animate([{ transform:'scale(1.2)' }, { transform:'scale(.9)', offset:.4 }, { transform:'scale(1.05)', offset:.7 }, { transform:'scale(1)' }], { duration:480, easing:'ease-out' }); };
    });
    ks.forEach((k, i) => k.addEventListener('keydown', e => {
      k.classList.remove('ptr');
      const big = o.step * (o.big || 10), d = { ArrowRight:o.step, ArrowUp:o.step, ArrowLeft:-o.step, ArrowDown:-o.step, PageUp:big, PageDown:-big }[e.key];
      if (d != null){ e.preventDefault(); set(i, v[i] + (e.shiftKey && /Arrow/.test(e.key) ? Math.sign(d) * big : d)); say(i); }
      else if (e.key === 'Home' || e.key === 'End'){ e.preventDefault(); set(i, e.key === 'Home' ? -Infinity : Infinity); say(i); }
    }));
    paint();
    return { glide, get:() => v.slice(), knobs:ks };
  }

  /* Creativity: a temperature from 0 to 1, read as five named stops, with a sample line that rewrites itself in the tone */
  const NAMES = ['Precise', 'Focused', 'Balanced', 'Playful', 'Creative'];
  const SAMPLE = [
    'The export failed because the token expired. Renew it in Settings.',
    'The export failed: your access token expired. Renew it in Settings, then run it again.',
    "Your export didn't finish because its access token had expired. Renew it in Settings and try again.",
    'Your export tripped over an expired token. A quick renewal in Settings will get it moving.',
    'The export ran out of road when its token expired mid-trip. Renew it in Settings and send it on its way.'
  ];
  const band = x => Math.min(4, Math.round(x * 4)), sm = $('.sdx-sm span', r), stops = $$('.sdx-stops button', r), REC = .4;
  let shown = -1;
  const cr = track(q('cr'), { min:0, max:1, step:.05, big:4, vals:[.5], rec:REC, fmt:x => x.toFixed(2), text:x => `${x.toFixed(2)}, ${NAMES[band(x)]}${Math.abs(x - REC) < .001 ? ', recommended' : ''}`,
    change:([x]) => { $('.sdx-v', q('cr').parentElement).textContent = `${NAMES[band(x)]}, ${x.toFixed(2)}`; stops.forEach(b => b.setAttribute('aria-pressed', Math.abs(+b.dataset.v - x) < .001));
      const b = band(x); if (b !== shown){ shown = b; swap(sm, SAMPLE[b]); } } });
  const rec = $('.sdx-rec', r); rec.style.left = REC * 100 + '%';
  $('.sdx-rail', q('cr')).insertAdjacentHTML('beforeend', `<i class="sdx-notch" style="left:calc(10px + (100% - 20px) * ${REC})"></i>`);
  rec.onclick = () => cr.glide(0, REC);
  stops.forEach(b => b.onclick = () => cr.glide(0, +b.dataset.v));

  /* Tool calls per run: steps of 10, with a tick and a number at each step you can press */
  const T = [10, 20, 30, 40, 50], ticks = $('.sdx-ticks', r);
  ticks.innerHTML = T.map(t => `<button data-v="${t}" style="left:${(t - 10) / 40 * 100}%" aria-label="${t} tool calls"><i></i>${t}</button>`).join('');
  const mx = track(q('mx'), { min:10, max:50, step:10, big:2, vals:[30], fmt:x => x + ' calls', text:x => x + ' tool calls',
    change:([x]) => { $('.sdx-v', q('mx').parentElement).textContent = x + ' calls'; $$('button', ticks).forEach(b => b.setAttribute('aria-pressed', +b.dataset.v === x)); } });
  $$('button', ticks).forEach(b => b.onclick = () => mx.glide(0, +b.dataset.v));

  /* Cost per run: a range in dollars; its two knobs stay a step apart */
  const $f = x => '$' + x.toFixed(2);
  const co = track(q('co'), { min:0, max:1, step:.05, big:4, vals:[.1, .6], fmt:$f, text:(x, i) => (i ? 'At most ' : 'At least ') + $f(x),
    change:([a, b]) => { $('.sdx-v', q('co').parentElement).textContent = `${$f(a)} to ${$f(b)}`; } });

  // the preview's story: try the far end, take the agent's recommendation, read fewer tool calls, then narrow the budget
  if (r === c.st) c.story(async s => {
    await s.beat(3);
    await s.tap(stops[2]); await s.beat(4);
    await s.point(rec); await s.beat(3);
    await s.tap(rec); await s.beat(4);
    await s.tap($('button[data-v="20"]', ticks)); await s.beat(3);
    await s.point(co.knobs[1], false); await s.beat(1);
    co.glide(1, .35); await s.beat(3);
    s.away(); await s.beat(2);
  });
});
